with parsed as (select id, customer_id, created_at, coupon_codes, items, ship_to, exists(items, i -> i.price > 100) as has_premium_item, size(items) as num_items, try_cast(attributes['weight_kg'] as double) as weight_kg, transform(items, i -> i.product_id) as product_ids, size(attributes) as num_attributes from carts where hour(created_at) between 11 and 18) select *, last_value(num_items, true) over (partition by customer_id order by num_items, id rows between unbounded preceding and current row) as last_known_num_items, dense_rank() over (partition by customer_id order by num_items desc nulls last) as num_items_dense_rank from parsed
